int ext4_orphan_add(handle_t *handle, struct inode *inode) {
    struct super_block *sb = inode->i_sb;
    struct ext4_sb_info *sbi = EXT4_SB(sb);
    struct ext4_inode_info *ei = EXT4_I(inode);
    int err = 0;
    int add = 0;
    __u32 hash;

    if (is_handle_valid(handle) && sbi->s_journal) {
        down_write(&sbi->s_orphan_lock);
        if (!is_inode_in_orphan_list(inode)) {
            if (is_valid_orphan_inode(inode)) {
                err = journal_get_write_access(handle, ei->i_bh);
                if (err == 0) {
                    if (!has_inode_on_disk_orphan(inode)) {
                        update_orphan_in_superblock(sb, ei->i_ino);
                        mark_inode_dirty(handle, inode);
                        add = 1;
                    }
                    list_add(&ei->i_orphan, &sbi->s_orphan);
                }
            }
        }
        up_write(&sbi->s_orphan_lock);
        if (add && err == 0) {
            handle->h_err = 0;
            err = 0;
        }
    } else {
        err = -EINVAL;
    }
    return err;
}

int ext4_orphan_add(handle_t *handle, struct inode *inode)
{
    struct super_block *sb = inode->i_sb;
    struct ext4_sb_info *sbi = EXT4_SB(sb);
    struct ext4_inode_info *ei = EXT4_I(inode);
    int err = 0;
    int hash;

    if (!EXT4_HAS_JOURNAL(sb))
        return 0;

    if (!S_ISREG(inode->i_mode) && !S_ISDIR(inode->i_mode) &&
        !S_ISLNK(inode->i_mode))
        return 0;

    hash = ext4_get_hash(inode);
    down_write(&sbi->s_orphan_lock);

    if (ei->i_hash_ino) {
        up_write(&sbi->s_orphan_lock);
        return 0;
    }

    err = ext4_journal_get_write_access(handle, sb, ei->i_bh, GFP_NOFS);
    if (err) {
        up_write(&sbi->s_orphan_lock);
        return err;
    }

    ei->i_dtime = 0;
    ei->i_ctime = ei->i_mtime = ei->i_atime = CURRENT_TIME;
    ei->i_hash_ino = cpu_to_le32(hash);
    err = ext4_handle_dirty_metadata(handle, NULL, ei->i_bh);
    if (err) {
        up_write(&sbi->s_orphan_lock);
        return err;
    }

    if (sbi->s_li_info && !sbi->s_li_info->s_orphan_pending)
        ext4_li_info_orphan_add(sbi->s_li_info);

    list_add(&ei->i_orphan, &sbi->s_orphan);
    sbi->s_orphan_count++;
    sb->s_dirt = 1;

    up_write(&sbi->s_orphan_lock);
    return 0;
}

int ext4_orphan_add(handle_t *handle, struct inode *inode)
{
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_super_block *es = &(EXT4_SB(inode->i_sb)->s_es);
    int err = 0;

    if (!EXT4_HAS_JOURNAL(inode->i_sb))
        return 0;

    mutex_lock(&EXT4_SB(inode->i_sb)->s_orphan_lock);

    if (ei->i_orphan) {
        mutex_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
        return 0;
    }

    if (!S_ISREG(inode->i_mode) && !S_ISDIR(inode->i_mode) &&
        !S_ISLNK(inode->i_mode)) {
        mutex_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
        return -EINVAL;
    }

    err = ext4_journal_get_write_access(handle, inode->i_sb, ei->i_bh, 0);
    if (err) {
        mutex_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
        return err;
    }

    if (es->s_orphans[0] == 0) {
        es->s_orphans[0] = cpu_to_le32(inode->i_ino);
        EXT4_SB(inode->i_sb)->s_dirt = 1;
        err = ext4_handle_dirty_metadata(handle, NULL, inode->i_sb);
        if (err) {
            mutex_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
            return err;
        }
    }

    ei->i_orphan = 1;
    list_add(&ei->i_orphan_list, &EXT4_SB(inode->i_sb)->s_orphan_list);
    mutex_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);

    return err;
}

int ext4_add_orphan (handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct ext4_orphan_list *orphan;
    int err = 0;

    if (!EXT4_HAS_JOURNAL(inode->i_sb))
        return -EROFS;

    mutex_lock(&sbi->s_orphan_lock);

    if (ext4_has_feature_orphan(inode->i_sb)) {
        if (!list_empty(&ei->i_orphan)) {
            mutex_unlock(&sbi->s_orphan_lock);
            return 0;
        }
    }

    if (!S_ISDIR(inode->i_mode) && !S_ISREG(inode->i_mode) &&
        !S_ISLNK(inode->i_mode)) {
        mutex_unlock(&sbi->s_orphan_lock);
        return -EINVAL;
    }

    err = ext4_journal_get_write_access(handle, inode->i_sb->s_jdev, 0);
    if (err < 0)
        goto out;

    orphan = &sbi->s_orphan;
    ei->i_orph = cpu_to_le32(inode->i_ino);
    err = ext4_mark_inode_dirty(handle, inode);
    if (err < 0)
        goto out;

    list_add(&ei->i_orphan, &orphan->list);
    orphan->count++;

    if (ext4_has_feature_orphan(inode->i_sb))
        ext4_set_orphan(inode);

out:
    mutex_unlock(&sbi->s_orphan_lock);
    return err;
}
